package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code householdId} — a stable identifier derived from the normalized last name
 * and address (see {@link Household}). Because the derivation is deterministic, every owner at the same
 * household (including one that joined an existing household via {@code sharesHousehold}) receives the
 * same value, which is then persisted and returned.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(Household.id(owner.getLastName(), owner.getAddress()));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Single source of truth for household identity. A household groups owners that share the same last
 * name and the same address, compared case-insensitively with surrounding and internal whitespace
 * collapsed (so "Smith" / " smith " and "10  Main St" / "10 Main St" belong together).
 *
 * <p>The {@link #id(String, String)} derived from that normalized pair is stable: the same last name
 * and address always map to the same value, so every member of a household — including one that joins
 * via {@code sharesHousehold} — receives an identical {@code householdId}.
 */
final class Household {

    private Household() {
    }

    /** Lower-case (locale-independent) with leading/trailing and repeated internal whitespace collapsed. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * The canonical household key for a (lastName, address) pair — the single definition of household
     * membership. Two owners belong to the same household exactly when their keys are equal; {@link #id}
     * hashes this same key, so the duplicate check and the assigned id can never diverge.
     *
     * <p>Addresses are compared in their {@link OwnerAddress normalized} form (whitespace collapsed,
     * upper-cased, abbreviations expanded) so that equivalent spellings — "12 main st" and
     * "12 MAIN STREET" — belong to the same household even when stored data was not normalized.
     */
    static String key(String lastName, String address) {
        return normalize(lastName) + "\n" + OwnerAddress.normalize(address);
    }

    /**
     * Stable household identifier for the given last name and address: {@code "H-"} followed by the
     * first 12 hex characters of the SHA-256 of the {@link #key household key}.
     */
    static String id(String lastName, String address) {
        String key = key(lastName, address);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder("H-");
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a new owner who belongs to the same household as an existing owner — same last name and same
 * address — so the request is answered with a 409 Conflict rather than persisting a duplicate household
 * member. Last name and address are compared case-insensitively with surrounding and internal whitespace
 * collapsed, so "Smith" / " smith " and "10  Main St" / "10 Main St" collide.
 *
 * <p>The caller can opt in to sharing a household by setting {@code sharesHousehold} true on the request,
 * which skips this check (e.g. a spouse or flatmate registering under the same roof). Runs after
 * {@link CheckTelephoneUnique} and before {@link BuildOwner}.
 */
public class CheckHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String key = Household.key(request.getLastName(), request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (key.equals(Household.key(existing.getLastName(), existing.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Computes the owner's {@code namesakeCount} — the number of owners that already exist (before this
 * create) sharing the same first name and last name, compared case-insensitively. Assigned at creation
 * and then persisted and returned. Runs before {@link SaveOwner} so the new owner is not counted.
 */
public class CountNamesakes {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (equalsIgnoreCase(firstName, existing.getFirstName())
                    && equalsIgnoreCase(lastName, existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}

